<script lang="ts">
  import { onMount } from 'svelte'; import { Button } from 'm3-svelte';
  import { api, errorMessage, type Project, type Run, type Service } from '$lib/api';
  let runs: Run[] = []; let services: Service[] = []; let projects: Project[] = []; let selected: Run | undefined; let projectId = ''; let service = ''; let deployment = ''; let kind: Parameters<typeof api.createRun>[0]['kind'] = 'validation'; let error = ''; let loading = true; let loaded = false; let busy = false;
  async function load() { loading = true; loaded = false; error = ''; try { const [r, s, p] = await Promise.all([api.runs(), api.services(), api.projects()]); runs = r.runs; services = s.services; projects = p.projects; if (!projects.some(project => project.id === projectId)) projectId = ''; loaded = true; } catch (e) { error = errorMessage(e); } finally { loading = false; } }
  async function create() { busy = true; error = ''; try { selected = await api.createRun({ project_id: projectId, service, deployment, kind }); loaded = false; runs = (await api.runs()).runs; loaded = true; } catch (e) { error = errorMessage(e); } finally { busy = false; } }
  async function inspect(id: string) { busy = true; error = ''; try { selected = await api.run(id); } catch (e) { error = errorMessage(e); } finally { busy = false; } }
  onMount(load);
</script>
<div class="page"><div class="heading"><div><h1>Runs</h1><p class="subtitle">Validation and benchmark evidence belongs to a deployment revision.</p></div><Button variant="outlined" onclick={load}>Refresh</Button></div>{#if error}<div class="error" role="alert">{error}</div>{/if}
{#if loading}<p role="status">Loading runs…</p>{:else if loaded && !runs.length}<p class="muted">No runs returned.</p>{:else if loaded}<div class="table-wrap"><table><thead><tr><th>Run</th><th>Service</th><th>Deployment</th><th>Kind</th><th>Revision</th><th>State</th><th>Action</th></tr></thead><tbody>{#each runs as run}<tr><td>{run.id}</td><td>{run.service}</td><td>{run.deployment}</td><td>{run.kind}</td><td>{run.revision}</td><td>{run.state}</td><td><Button variant="text" disabled={busy} onclick={() => inspect(run.id)}>Inspect</Button></td></tr>{/each}</tbody></table></div>{/if}
{#if selected}<section class="section"><h2>Run {selected.id}</h2><p>{selected.kind} · {selected.service} / {selected.deployment}</p><p>Revision: <code>{selected.revision}</code> · State: {selected.state}</p></section>{/if}
<section class="section"><h2>Start a run</h2><form class="panel form stack" onsubmit={(event) => { event.preventDefault(); create(); }}><label>Project<select required bind:value={projectId}><option value="" disabled>Select a project</option>{#each projects as project}<option value={project.id}>{project.name} ({project.team})</option>{/each}</select></label>{#if loaded && !projects.length}<p class="muted">No projects available. Create a project before starting a run.</p>{/if}<label>Service<select required bind:value={service} onchange={() => { deployment = ''; }}><option value="" disabled>Select a service</option>{#each services as item}<option value={item.name}>{item.name}</option>{/each}</select></label><label>Deployment<select required bind:value={deployment}><option value="" disabled>Select a deployment</option>{#each services.find(item => item.name === service)?.deployments || [] as item}<option value={item.name}>{item.name}</option>{/each}</select></label><label>Kind<select bind:value={kind}><option value="validation">Validation</option><option value="benchmark">Benchmark</option></select></label><div><Button type="submit" disabled={busy || loading || !loaded}>Start run</Button></div></form></section></div>
